import { initializeApp } from 'firebase/app';
import { getFirestore } from 'firebase/firestore';
import { getAuth } from 'firebase/auth';

// 현재 환경 정보 로깅
const isGitHubPages = window.location.hostname === 'gooddaysyk.github.io';
console.log('Current environment:', {
  hostname: window.location.hostname,
  protocol: window.location.protocol,
  href: window.location.href,
  isGitHubPages
});

// Firebase 설정
const firebaseConfig = {
  apiKey: "AIzaSyDWAFLA7k2qSTRfqzYBLwpDtjzt68j08_M",
  // GitHub Pages에서도 Firebase의 기본 authDomain을 사용
  authDomain: "daily-quotes-app-9bf66.firebaseapp.com",
  projectId: "daily-quotes-app-9bf66",
  storageBucket: "daily-quotes-app-9bf66.appspot.com",
  messagingSenderId: "287571952965",
  appId: "1:287571952965:web:b6801a07c2869e10792a2c",
  measurementId: "G-9SLLSGH4VJ"
};

let app, auth, db;

try {
  // Firebase 초기화
  app = initializeApp(firebaseConfig);

  // Auth 인스턴스 초기화
  auth = getAuth(app);
  
  // GitHub Pages에서 실행 중일 때 auth 설정 수정
  if (isGitHubPages) {
    auth.config.authDomain = firebaseConfig.authDomain;
    auth.config.redirectUrl = `https://gooddaysyk.github.io/dailythought/`;
  }
  
  // Firestore 인스턴스 초기화
  db = getFirestore(app);

  // 인증 상태 변경 감지 및 디버깅
  auth.onAuthStateChanged((user) => {
    console.log('Auth state changed:', {
      isSignedIn: !!user,
      userId: user?.uid,
      config: auth.config,
      currentUser: auth.currentUser,
      apiKey: firebaseConfig.apiKey,
      authDomain: firebaseConfig.authDomain
    });
  });
} catch (error) {
  console.error('Firebase initialization error:', error);
  throw error;
}

export { app, db, auth }; 